use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfileFamilyNameAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileFamilyNameAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfileFamilyNameAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getFamilyName returns null on a freshly created holder.
     */
    public function testFamilyNameNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileFamilyNameAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isFamilyNameAssigned());
        $this->assertNull($holder->getFamilyName());
    }
}
class ImplWithUserProfileFamilyNameAttributeHolderUnitTest
{
    use UserProfileFamilyNameAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedFamilyNameRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultFamilyName();
    }
}
